/** A snapshot an extension sends after each render: everything it shows in the notch and its Settings page. */
export interface Snapshot {
  protocolVersion: 1;
  type: "snapshot";
  extensionID: string;
  /** Increases with every snapshot from the same runner. */
  revision: number;
  surfaces: Surface[];
  settings?: UINode;
}

export interface Surface {
  id: string;
  kind: SurfaceKind;
  title: string;
  initialView: Presentation;
  phase: SurfacePhase;
  compact?: CompactContent;
  expanded: UINode;
  peek?: PeekContent;
  idlePreview?: boolean;
}

export type SurfaceKind = "activity" | "prompt";

export type Presentation = "compact" | "expanded";

export type SurfacePhase = "active" | "paused" | "completed" | "pending";

export interface CompactContent {
  leading: UINode[];
  trailing: UINode[];
}

/** A short announcement. A new id announces a new event; ordinary snapshots keep the same id. */
export interface PeekContent {
  /** Change for each new event; keep stable during routine renders. */
  id: string;
  text: string;
  duration: number;
}

export interface UINode {
  id: string;
  type: NodeType;
  props: NodeProps;
  children: UINode[];
}

export type NodeType = "column" | "row" | "text" | "symbol" | "progress" | "button" | "textField" | "artwork" | "waveform" | "player" | "spacer" | "divider" | "toggle" | "section" | "listItem" | "badge" | "picker";

export interface NodeProps {
  text?: string;
  name?: string;
  tone?: Tone;
  size?: TextSize;
  /** Progress, from zero to one. */
  value?: number;
  action?: string;
  placeholder?: string;
  disabled?: boolean;
  source?: string;
  media?: NowPlayingState;
  /** Secondary line: list item subtitle or section footer. */
  detail?: string;
  spacing?: Spacing;
  align?: Alignment;
  /** Picker choices; `selection` holds the chosen value. */
  options?: PickerOption[];
  selection?: string;
  /** What VoiceOver says for a symbol, an icon-only button, a progress bar or a field. */
  label?: string;
}

export type Tone = "primary" | "secondary" | "accent" | "success" | "warning" | "danger";

export type TextSize = "caption" | "body" | "headline" | "title" | "timer";

export type Spacing = "none" | "tight" | "regular" | "loose";

export type Alignment = "start" | "center" | "end";

export interface PickerOption {
  value: string;
  label: string;
}

export interface NowPlayingState {
  id: string;
  eventID: string;
  player: string;
  playerName?: string;
  title: string;
  artist: string;
  album: string;
  /** Bounded JPEG/PNG data or an https URL on a host the extension lists in `imageHosts`. */
  artwork?: string;
  duration: number;
  position: number;
  isPlaying: boolean;
  volume: number;
  shuffle: boolean;
  repeating: boolean;
  /** Seconds since 1970 when `position` was read. */
  updatedAt: number;
}

/** A tap, toggle or text the user sent to an extension. */
export interface UserEvent {
  protocolVersion: 1;
  type: "event";
  action: string;
  value?: string;
}

export type JSONValue = null | boolean | number | string | JSONValue[] | { [key: string]: JSONValue };

export interface ConnectionCommand {
  protocolVersion: 1;
  type: "connectionCommand";
  extensionID: string;
  requestID: string;
  /** A connection declared in the manifest; empty for operations the app answers itself (fetch, secrets, openURL). */
  connectionID: string;
  operation: ConnectionOperation;
  sessionID?: string;
  request?: ConnectionHTTPRequest;
  /** For `fetch`, which uses no declared connection; `connectionID` is empty. */
  fetch?: NetworkRequest;
  /** For the `secret…` operations; `connectionID` is empty. */
  secret?: SecretRequest;
  /** For `openURL`; `connectionID` is empty. */
  url?: string;
  message?: JSONValue;
  /** `false` fails instead of asking the user when access was not granted before. */
  interactive?: boolean;
}

export type ConnectionOperation = "request" | "open" | "send" | "close" | "fetch" | "secretGet" | "secretSet" | "secretDelete" | "openURL";

export interface ConnectionResponse {
  protocolVersion: 1;
  type: "connectionResponse";
  requestID: string;
  result?: JSONValue;
  error?: string;
}

export interface ConnectionEvent {
  protocolVersion: 1;
  type: "connectionEvent";
  connectionID: string;
  sessionID: string;
  event: "message" | "closed";
  message?: JSONValue;
  error?: string;
}

/** A request to a declared local HTTP connection. */
export interface ConnectionHTTPRequest {
  path: string;
  method: HTTPMethod;
  headers?: Record<string, string>;
  body?: string;
  timeoutMs?: number;
}

export type HTTPMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE" | "HEAD" | "OPTIONS";

/** An HTTPS request to a host listed in the manifest's `network`. */
export interface NetworkRequest {
  url: string;
  method: HTTPMethod;
  headers?: Record<string, string>;
  body?: string;
  timeoutMs?: number;
}

/** A key in the extension's own Keychain items, and the value for `secretSet`. */
export interface SecretRequest {
  key: string;
  value?: string;
}

/** notchnotch.json: what an extension is, what it may reach and the settings it asks for. */
export interface ExtensionManifest {
  id: string;
  name: string;
  version: string;
  apiVersion: 1;
  entry: "bundle.js";
  /** `local-network` for loopback HTTP and WebSocket connections, `process` for native helpers. */
  permissions: ("local-network" | "process")[];
  /** Named local destinations: loopback HTTP or WebSocket services and native helpers. */
  connections?: Record<string, ConnectionDefinition>;
  /** An SF Symbol name, or the file name of a 512×512 PNG in the package's assets/ folder (such as icon.png). An optional name@dark.png beside it is used on dark backgrounds. */
  icon?: string;
  description?: string;
  /** HTTPS hosts the app may fetch Artwork from for this extension. An exact DNS name or a *.subdomain wildcard (which does not match the bare domain). */
  imageHosts?: string[];
  /** HTTPS hosts the extension may reach with fetch. An exact DNS name or a *.subdomain wildcard (which does not match the bare domain). */
  network?: string[];
  /** Settings NotchNotch asks for, stores and draws natively in Setup. Values reach the extension through getPreferenceValues(). */
  preferences?: ExtensionPreference[];
  /** Store handle of the publisher, such as a GitHub user name. */
  author?: string;
  /** One to three entries from `ExtensionCategory.all`. */
  categories?: ExtensionCategoryName[];
  homepage?: string;
  repository?: string;
  /** An SPDX license expression, such as MIT. */
  license?: string;
}

/** One setting declared in the manifest. The app stores its value, draws the field in Setup and hands the values to the extension when it starts. */
export interface ExtensionPreference {
  name: string;
  type: PreferenceKind;
  title: string;
  description?: string;
  placeholder?: string;
  required?: boolean;
  default?: string | boolean;
  /** Choices for a dropdown. */
  options?: PreferenceOption[];
}

export type PreferenceKind = "text" | "password" | "toggle" | "dropdown";

export interface PreferenceOption {
  value: string;
  title: string;
}

export type ExtensionCategoryName = "Communication" | "Developer Tools" | "Finance" | "Fun" | "Health" | "Media" | "News" | "Productivity" | "Sports" | "System" | "Weather" | "Other";

/** A declared local destination: a loopback HTTP or WebSocket service, or a native helper started over stdio. */
export interface ConnectionDefinition {
  transport: ConnectionTransport;
  endpoint?: string;
  executable?: string;
  arguments?: string[];
}

export type ConnectionTransport = "http" | "websocket" | "stdio";
